/** business: новый кандидат со ссылкой (канал link_only — ничего не отправляется). Возвращает ссылку /c/… */
export async function createCandidateLink(page: Page, name: string, simulation: string = SIMULATION): Promise<string> {
  await page.goto('/candidates/new');
  const sim = page.locator('#candidate-simulation_id');
  await expect(sim).toBeVisible();
  const opts = await sim.locator('option').evaluateAll((o) => (o as HTMLOptionElement[]).map((x) => ({ v: x.value, t: x.textContent || '' })));
  const target = opts.filter((o) => o.v && o.t.includes(simulation));
  expect(target, `нет активной симуляции «${simulation}» (QA_CALL_SIMULATION / QA_LONG_SIMULATION)`).toHaveLength(1);
  const managers = await page.locator('#candidate-assigned_manager_id option').evaluateAll((o) =>
    (o as HTMLOptionElement[]).map((x) => ({ v: x.value, t: x.textContent || '' })).filter((x) => x.v),
  );
  await page.locator('#candidate-full_name').fill(name);
  await page.locator('#candidate-phone').fill('05000094' + String(10 + Math.floor(Math.random() * 90)));
  await page.locator('#candidate-role_title').fill('QA-AUTO נציג');
  await page.locator('#candidate-assigned_manager_id').selectOption((managers.find((m) => m.t.includes('fdfdf')) || managers[0]).v);
  await sim.selectOption(target[0].v);
  await page.locator('input[name=send_channel][value=link_only]').check();
  await page.getByRole('button', { name: /יצירת קישור/ }).click();
  let link = '';
  await expect
    .poll(async () => {
      link = ((await page.content()).match(/https?:\/\/[^"'<\s]*\/c\/[A-Za-z0-9_\-]+/) || [''])[0];
      return link;
    }, { message: 'ссылка кандидата /c/… не появилась', timeout: 30_000 })
    .not.toBe('');
  return link;
}

/** business: строка кандидата в /candidates (поиск по имени). */
export async function candidateRow(page: Page, name: string): Promise<Locator> {
  await page.goto('/candidates');
  await expect(page.getByRole('heading', { level: 1, name: 'מועמדים' })).toBeVisible();
  const search = page.getByRole('searchbox').or(page.getByPlaceholder(/חיפוש/)).first();
  if (await search.isVisible()) await search.fill(name);
  const row = page.getByRole('row').filter({ hasText: name });
  await expect(row, `нет строки кандидата «${name}» в /candidates`).toHaveCount(1);
  return row;
}

export type Candidate = { browser: Browser; ctx: BrowserContext; page: Page; counts: { start: number; voice: number } };

/** Отдельный Chrome кандидата с фальшивым микрофоном; считает POST candidate_start_attempt и start-voice-session. */
export async function launchCandidate(viewport: { width: number; height: number }, wav: string = WAV): Promise<Candidate> {
  const browser = await chromium.launch({
    channel: process.env.QA_CALL_CHANNEL || 'chrome',
    args: [
      '--use-fake-ui-for-media-stream',
      '--use-fake-device-for-media-stream',
      `--use-file-for-fake-audio-capture=${wav}`,
      '--autoplay-policy=no-user-gesture-required',
    ],
  });
  const mobile = viewport.width < 768;
  const ctx = await browser.newContext({ locale: 'he-IL', viewport, isMobile: mobile, hasTouch: mobile, permissions: ['microphone'] });
  // #d9d257: список RTCPeerConnection страницы — чтобы в тесте обрыва практики закрыть WebRTC, как при настоящем сбое.
  await ctx.addInitScript(() => {
    const O = window.RTCPeerConnection;
    if (!O) return;
    const pcs: RTCPeerConnection[] = [];
    (window as unknown as { __qaPcs: RTCPeerConnection[] }).__qaPcs = pcs;
    const W = function (this: unknown, ...a: ConstructorParameters<typeof RTCPeerConnection>) {
      const pc = new O(...a);
      pcs.push(pc);
      return pc;
    } as unknown as typeof RTCPeerConnection;
    W.prototype = O.prototype;
    Object.setPrototypeOf(W, O);
    window.RTCPeerConnection = W;
  });
  const page = await ctx.newPage();
  const counts = { start: 0, voice: 0 };
  page.on('request', (r) => {
    if (r.method() !== 'POST') return;
    const u = r.url();
    if (u.includes('/rpc/candidate_start_attempt')) counts.start++;
    if (u.includes('/functions/v1/start-voice-session')) counts.voice++;
  });
  return { browser, ctx, page, counts };
}

/** Кнопка по имени: дождаться и нажать. */
export async function tap(page: Page, name: string | RegExp, timeout = 30_000) {
  const b = page.getByRole('button', { name }).first();
  await expect(b).toBeVisible({ timeout });
  await b.click();
}

