/** Сообщение о сбое старта и его кнопки. Возвращает самый внутренний блок, где есть и текст, и «נסו שוב». */
export async function expectStartFailure(page: Page, text: RegExp): Promise<Locator> {
  const msg = page.getByText(text);
  await expect(msg).toBeVisible({ timeout: 15_000 });
  const retry = page.getByRole('button', { name: TXT.retry });
  await expect(retry).toBeVisible();
  await expect(page.getByRole('button', { name: TXT.help })).toBeVisible();
  return page.locator('div').filter({ has: msg }).filter({ has: retry }).last();
}

/** Путь к человеку: лист «צריכים עזרה?» открывается, Esc возвращает к сообщению. */
export async function expectHelpPath(page: Page, text: RegExp) {
  await tap(page, TXT.help);
  await expect(page.getByText(TXT.helpSheet)).toBeVisible();
  await page.keyboard.press('Escape');
  await expect(page.getByText(TXT.helpSheet)).toBeHidden();
  await expect(page.getByText(text)).toBeVisible();
}

/**
 * Подсказка на экране подключения видна ~0,5 с — ожидание ставится ДО нажатия и возвращает её текст.
 * Использование: const hint = waitConnectingHint(page); await tap(...); expect(await hint).toBe(TXT.hint)
 */
export function waitConnectingHint(page: Page): Promise<string> {
  return page
    .waitForFunction(() => {
      const el = document.querySelector('[data-testid="call-connecting-hint"]') as HTMLElement | null;
      return el && el.offsetParent !== null ? (el.textContent || '').trim() : '';
    }, undefined, { timeout: 30_000 })
    .then((h) => h.jsonValue() as Promise<string>);
}

export async function scrollWidth(page: Page) {
  return page.evaluate(() => ({ sw: document.documentElement.scrollWidth, vw: window.innerWidth }));
}

