/**
 * Страховка для проверок без звонка: любой старт попытки (candidate_start_attempt) и голосовой сессии
 * (start-voice-session) обрывается и считается — официальная попытка и OpenAI не тратятся.
 */
export async function blockCallStarts(page: Page) {
  const blocked = { start: 0, voice: 0 };
  await page.route('**/rest/v1/rpc/candidate_start_attempt', (r) => {
    if (r.request().method() === 'POST') blocked.start++;
    return r.abort('failed');
  });
  await page.route('**/functions/v1/start-voice-session', (r) => {
    if (r.request().method() === 'POST') blocked.voice++;
    return r.abort('failed');
  });
  return blocked;
}

