/** Сбой посреди звонка: сеть выключена и WebRTC закрыт (как в ручной проверке 14.10, сценарий B). */
export async function dropCall(ctx: BrowserContext, page: Page) {
  await ctx.setOffline(true);
  await page.evaluate(() => (window as unknown as { __qaPcs?: RTCPeerConnection[] }).__qaPcs?.forEach((pc) => pc.close()));
}

/** Секунды на таймере звонка «M:SS» (обратный отсчёт). */
export async function timerSeconds(page: Page): Promise<number> {
  const t = await page.getByText(/^\d:\d\d$/).first().textContent();
  const m = (t || '').trim().match(/^(\d):(\d\d)$/);
  return m ? Number(m[1]) * 60 + Number(m[2]) : NaN;
}
